def load_dataset():
    raw = zlib.decompress(base64.b64decode("".join(_DATASET_B64)))
    sha = hashlib.sha256(raw).hexdigest()
    if sha != DATASET_SHA256:
        raise RuntimeError(f"embedded dataset corrupted: sha256 {sha} != {DATASET_SHA256}")
    df = pd.DataFrame(json.loads(raw.decode("ascii")))
    if len(df) != DATASET_ROWS or df.duplicated(["model", "row_id", "repeat"]).any():
        raise RuntimeError(f"embedded dataset has {len(df)} rows / duplicate row_ids")
    return df


DATASET = load_dataset()
# One evaluation row per original Silent Stop: (row_id, repeat = which pilot run of this model).
# The leaderboard task keeps only the calling model's rows.
ALL_EVAL = DATASET[["row_id", "repeat", "model", "transcript", "prior"]].copy()
ALL_EVAL.index = [f"{DATASET_SHA256[:10]}-{m.split('/')[-1]}-{rid}-r{k}"
                  for m, rid, k in zip(ALL_EVAL.model, ALL_EVAL.row_id, ALL_EVAL.repeat)]
print(f"dataset {DATASET_NAME}: {len(DATASET)} Silent Stops from {DATASET.model.nunique()} models "
      f"(sha256 {DATASET_SHA256[:12]})")


def _model_name(llm):
    return str(getattr(llm, "model", None) or getattr(llm, "name", None) or "unknown")


def _opt_int(v):
    return None if v is None else int(v)


